import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the defaults mode="fast" and level="3".

    keys[i] is set to values[i]. Returns the resulting values ordered as:
    mode, level, then every other key in order of first appearance in `keys`.

    If a key repeats, the last value given for it wins, and it keeps the
    position of its first appearance. Raises ValueError if `keys` and
    `values` have different lengths. Performs no I/O.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    result: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        result[k] = v
    return list(result.values())


def test_no_overrides_gives_defaults() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode_only() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level_only() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_in_reverse_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_follow_in_given_order() -> None:
    assert settings(["z", "a", "m"], ["1", "2", "3"]) == ["fast", "3", "1", "2", "3"]


def test_extra_keys_mixed_with_defaults_keys() -> None:
    assert settings(["x", "level", "y", "mode"], ["a", "5", "b", "slow"]) == [
        "slow",
        "5",
        "a",
        "b",
    ]


def test_duplicate_key_last_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_duplicate_extra_key_keeps_first_position() -> None:
    assert settings(["p", "q", "p"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_empty_string_values_are_kept() -> None:
    assert settings(["mode", "x"], ["", ""]) == ["", "3", ""]


def test_does_not_mutate_inputs() -> None:
    keys = ["x", "mode"]
    values = ["1", "slow"]
    settings(keys, values)
    assert keys == ["x", "mode"]
    assert values == ["1", "slow"]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings([], ["1"])

